<?php

declare(strict_types=1);

require_once dirname(__DIR__, 2) . '/config.php';
require_once ROOT_PATH . '/database/config/db.php';
require_once ROOT_PATH . '/security/middleware/AuthMiddleware.php';
require_once ROOT_PATH . '/services/CoworkspaceService.php';

AuthMiddleware::startSession();
$user = AuthMiddleware::requireAuth();
$db = Database::getInstance();
$workspaceId = (int)($_GET['workspace_id'] ?? 0);
$whiteboardId = (int)($_GET['whiteboard_id'] ?? 0);
$channelId = (int)($_GET['channel_id'] ?? 0);
if ($workspaceId < 1 || $whiteboardId < 1 || $channelId < 1) { http_response_code(400); exit('A Coworkspace whiteboard session is required.'); }
$uid = (int)$user['id'];
$workspace = CoworkspaceService::get($db, $workspaceId, $uid);
if (!$workspace) { http_response_code(403); exit('You do not have access to this Coworkspace.'); }
$stmt = $db->prepare('SELECT wb.id,wb.title,wb.description,wb.visibility,wb.public_permission,wb.created_by,cw.server_id,cw.channel_id,cw.host_id FROM collab_whiteboards wb INNER JOIN collab_workspaces cw ON cw.id=wb.workspace_id WHERE wb.id=:id AND wb.workspace_id=:wid LIMIT 1');
$stmt->execute([':id'=>$whiteboardId,':wid'=>$workspaceId]);
$board=$stmt->fetch(PDO::FETCH_ASSOC);
if(!$board){http_response_code(404);exit('Whiteboard session not found.');}
$serverId=(int)$board['server_id'];$workspaceChannelId=(int)$board['channel_id'];
if($serverId<1||$workspaceChannelId<1||$workspaceChannelId!==$channelId){http_response_code(400);exit('Invalid Coworkspace navigation context.');}
$isOwner=(int)$board['created_by']===$uid||(int)$board['host_id']===$uid;
$stmt=$db->prepare('SELECT permission FROM collab_resource_permissions WHERE resource_type="whiteboard" AND resource_id=:rid AND user_id=:uid LIMIT 1');$stmt->execute([':rid'=>$whiteboardId,':uid'=>$uid]);$explicitPermission=$stmt->fetchColumn();
$publicPermission=strtolower((string)($board['public_permission']??'view'));if(!in_array($publicPermission,['view','comment','edit'],true))$publicPermission='view';
$accessPermission=$isOwner?'edit':($explicitPermission!==false?strtolower((string)$explicitPermission):($board['visibility']==='public'?$publicPermission:'view'));if(!in_array($accessPermission,['view','comment','edit'],true))$accessPermission='view';
if(!$isOwner&&$board['visibility']==='private'&&$explicitPermission===false){http_response_code(403);exit('This private whiteboard has not been shared with you.');}
$csrf=AuthMiddleware::csrfToken();$title=(string)$board['title'];
?>
